"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def RemovePunctuation(sentence):
    punctuation_set = set(['.', ',', '!', '?', ';', ':', '-', "'", '"', '(', ')'])
    clean_sentence = ''
    for __reserved_keyword__char in sentence:
        if (__reserved_keyword__char not in punctuation_set):
            clean_sentence = (clean_sentence + __reserved_keyword__char)
    return clean_sentence
